SELECT v.* FROM (VALUES
    (N'PNMC-ED-001', N'Módulos de capacitación para instrumentistas y directores de banda', NULL, NULL, NULL, N'La producción de los 10 módulos de capacitación para instrumentistas y directores de banda se propuso contribuir a mejorar y fortalecer las capacidades y habilidades musicales identificadas en un estudio diagnóstico en el que se identificaron serias deficiencias en la formación y en el cual se estableció con claridad las áreas de conocimiento en las que se hacía necesario adelantar programas de capacitación continua que con una innovadora metodología se convirtieran en una verdadera y accesible alternativa para salvar las principales dificultades detectadas. Se incluyen en cada módulo temas específicos 1- Lectura rítmica, 2- lectura melódica, 3- armonía funcional aplicada, 4- la melodía a dos, tres y cuatro voces. 5- dirección y montaje de repertorio, 6- transcripción para banda, 7- técnicas de orquestación, 8- banda escolar, 9- fundamentación instrumental, 10- formas musicales colombianas', N'1990/1992', 1990, 1992, NULL, N'es', N'Libro', N'Físico', N'Nacional', NULL, NULL, NULL, N'Banda', N'Pedagogía y formación', NULL, N'23.5 cm. x 22 cm', N'1- 26 p., 2- 52 p., 3- 21 p., 4- 34 p., 5- 32 p., 6- 48 p., 7- 38 p., 8- 15 p., 9- 41 p., 10- 25 p', NULL, N'/editorial/thumbs/PNMC-ED-001.jpg', N'2', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-002', N'Música vocal escolar', NULL, N'Vol. 1', N'Música vocal escolar', N'Una recopilación de materiales musicales diversos, ejercicios musicales y sencillas composiciones que amplían el repertorio vocal infantil y juvenil. Contiene partituras, con línea melódica, cifrado armónico y texto, de 34 ejercicios rítmicos o canciones de compositores colombianos que han elaborado estas composiciones como experiencias educativas', N'1997', 1997, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'21.5 x 28 cm', N'50 p', NULL, N'/editorial/thumbs/PNMC-ED-002.jpg', N'8', N'Alta', 0, 1, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-003', N'Repertorio Vocal Tradicional de Colombia', NULL, N'Vol. 1', N'Repertorio Vocal Tradicional de Colombia', N'Recopilación de repertorio vocal tradicional sobre cantos, juegos y rimas de los departamentos de Magdalena, Valle y Cundinamarca, departamentos en los cuales se implementó el piloto del proyecto de coros escolares del Programa Nacional de Coros del Ministerio de Cultura en el año 2001. Hacen parte de esta publicación las partituras línea melódica y texto – de 29 canciones: 11 de la zona atlántica, 8 de la zona andina y 10 de la zona pacífica', N'2001', 2001, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'21 x 27.5 cm', N'44 p', NULL, N'/editorial/thumbs/PNMC-ED-003.jpg', N'8', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-004', N'Música Coral Colombiana', NULL, NULL, NULL, N'Una publicación dedicada a la práctica y la expresión coral en el país en la que participan 8 compositores colombianos con sus creaciones corales inéditas de exigente nivel, con una selección de doce obras corales para 4 voces (partitura general o score) realizado en el marco del Programa Nacional de Coros del Ministerio de Cultura. Esta edición se propone aportar al repertorio coral colombiano, invitar a intérpretes y formadores a establecer una cadena productiva de creación, interpretación y divulgación con el fin de impulsar, fomentar y facilitar el conocimiento, la apropiación y la circulación de materiales dedicados a la actividad coral', N'2001', 2001, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'22 x 33 cm', N'112 p', NULL, N'/editorial/thumbs/PNMC-ED-004.jpg', N'9', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-005', N'Nuevos Cantos Infantiles Colombianos', NULL, NULL, NULL, N'Cancionero con repertorio coral infantil basado en aires y ritmos tradicionales de distintas regiones de Colombia, Esta publicación hace parte de la Beca de Creación de 1999 de la Convocatoria de Estímulos del Ministerio de Cultura. Incluye canciones al unísono, unísono con ostinatos, canon, canciones con dos o tres voces homofónicas, y a dos o tres voces polifónicas, en un CD con las pistas de acompañamiento y cada una de las voces internas grabadas por separado', N'2002', 2002, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'21.5x 27.5 cm', N'108 p', NULL, N'/editorial/thumbs/PNMC-ED-005.jpg', N'9', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-006', N'Colombia canta', NULL, NULL, NULL, N'Con ocasión de la celebración del bicentenario de las independencias, el cancionero Colombia Canta reúne 64 canciones – dos de cada departamento- representativas del repertorio musical del país. La publicación contiene las partituras transcritas y editadas con su línea melódica, texto y cifrado armónico. (Coedición con Fundación Nacional Batuta)', N'2010', 2010, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'21.5 x 28 cm', N'196 p', NULL, N'/editorial/thumbs/PNMC-ED-006.jpg', N'10', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-007', N'Temas En-Cantados', N'Cancionero para niños y jóvenes', NULL, NULL, N'Temas En Cantados – Cancionero para niños y jóvenes, es una recopilación de 50 canciones, en cuatro categorías: canciones en ritmos colombianos, canciones urbanas, música coral y juegos musicales y rítmicos. El PDF interactivo de esta publicación incluye la partitura de cada canción vinculada a su versión de audio. En su mayoría, las pistas de audio incluyen un antecompás con la muestra de acompañamiento rítmico de la canción. Las versiones corales cuentan con pistas para cada una de las voces. (Libro con partituras y CD versión digital)', N'2014', 2014, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'22x 28 cm. + CDPáginas: 92 p', NULL, N'109’', N'/editorial/thumbs/PNMC-ED-007.jpg', N'10', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-008', N'Música vocal escolar', NULL, N'Vol. 2', N'Música vocal escolar', N'Para esta edición hemos contado con una selección de obras de los maestros: Amparo Ángel, Ángela Rueda de Haliday: María Teresa Martínez, Claudine Peñaloza, Miguel Ángel López, Miguel Ángel Arias, Alvaro Julio Agudelo, Julio Roberto Castillo, y la información de María Lucía Salgado, niña que desde su espacio escolar nos regaló una de las nuevas rimas citadinas que invita a la creación de juegos rítmicos corporales. Los elementos rítmicos, melódicos, armónicos, formales, y de contenido textual, de las obras seleccionadas, son contrastantes y con diversos grados de complejidad, lo que posibilita un ordenamiento metodológico en le cual las obras cuyo énfasis está en la estructura rítmica y textual, ocupan una primera parte; posteriormente vienen las canciones a una voz, ; canciones a una voz con acompañamiento de piano; un canon a cuatro voces iguales; melodía con ostinatos y percusión básica; melodía y tres ostinatos; canciones a dos voces y finalmente canciones a tres voces', N'2001', 2001, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'28cm. x 22cm', N'44 p', NULL, N'/editorial/thumbs/PNMC-ED-008.jpg', N'11', N'Alta', 0, 1, N'ISBN reconstruido del prefijo 958- (original PPT: 8052-92-0)', N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-009', N'Cantos para juegos, danzas y rondas en el chocó – CD', NULL, NULL, NULL, N'El disco realizado por el proyecto Música y Vida realizado en el Chocó por el Ministerio de Cultura, con participación de la Universidad Tecnológica del Chocó UTCH y cofinanciado con fondos de BID, República de Corera. Es un documento didáctico al servicio de los docentes o formadores de las Escuelas de Música del proyecto Música y Vida como material de apoyo en el desarrollo de actividades pedagógicas con los niños y jóvenes. Es un material de interés para investigadores, centros de formación y comunidad en general, con el propósito de divulgar, conocer y apropiar repertorio de músicas infantiles de la región pacífica y asimilados del repertorio infantil hispánico y portugués. (Apartes del texto del cuadernillo escritos por Leonidas Valencia Valencia) En este disco se incluyen 20 piezas, de las cuales 18 son de la tradición y 2 de', N'2014', 2014, NULL, NULL, N'es', N'CD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'14 x 12,5 cm', NULL, N'53’ Práctica Musical vocal, Coro', N'/editorial/thumbs/PNMC-ED-009.jpg', N'12', N'Alta', 0, 1, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-010', N'Música colombiana para banda, coro y formato tradicional andino', NULL, NULL, NULL, N'El proyecto Música colombiana para banda, coro y formato tradicional andino: Composiciones originales, arreglos y propuesta pedagógica y didáctica es una producción editorial en la cual se desarrolla una estrategia que se propuso reconocer el trabajo de Músicos compositores colombianos cuya formación, conocimiento, trayectoria y experiencia ha contribuido a visibilizar, enriquecer y fortalecer procesos de creación, formación y difusión de músicas regionales colombianas mediante convocatoria pública. Los participantes seleccionados demostraron mayor conocimiento, experiencia y trayectoria, valorando su producción y reconociendo sus contribuciones a los procesos de formación, además del entusiasmo y la motivación que propició la convocatoria. Este proyecto contribuye a dar a conocer y difundir el patrimonio musical colombiano a la apropiación de expresiones y prácticas de la música en los tres formatos y a la creación de nuevos repertorios, con un componente pedagógico y didáctico que fortalece el ejercicio de diversas tradiciones musicales colombianas, los procesos de formación musical favoreciendo el logro de capacidades y habilidades musicales de intérpretes, docentes y directores, agrupaciones musicales y a la consolidación de escuelas o proyectos de formación musical', N'2021', 2021, NULL, NULL, N'es', N'DVD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Prácticas vocales > Cancioneros > Palabra ritmada > Coro', N'Coro y música vocal', N'Cancionero', NULL, N'14 x 12,5 cm', NULL, N'53’ Práctica Musical vocal, Coro', N'/editorial/thumbs/PNMC-ED-010.jpg', N'13', N'Alta', 0, 1, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-011', N'Arreglos para banda - escuela', NULL, N'Volumen I', N'Arreglos para banda - escuela', N'Acento : Arreglos para banda –escuela. Volumen I Hace parte de un proyecto de elaboración y publicación de arreglos para banda a partir de parámetros específicos de dificultad técnica para los diversos instrumentos y la utilización de plantillas instrumentales estándar (reducida y básica). Incluye arreglos, score y partes, de seis piezas 4 de autor y 2 de la tradición: Amistad (Vals); Beautiful San Andrés (Calypso); Francisco alegre (Pasodoble); Hágame un tiple maestro (bambuco); La palma de chontaduro-Caderona (Abozao-Aire de juga) y Carnaval (golpe tradicional llanero)', N'2001', 2001, NULL, NULL, N'es', N'Libro partituras', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Arreglos', NULL, N'22.5x 31.5 cm', N'91 p. partitura general y 92 p. partes', NULL, N'/editorial/thumbs/PNMC-ED-011.jpg', N'15', N'Alta', 0, 0, N'ISBN reconstruido del prefijo 958- (original PPT: 8159-05-9)', N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-012', N'Acento', N'Arreglos para banda –escuela', N'Volumen II', N'Acento', N'Acento: Arreglos para banda –escuela. Volumen II Hace parte de un proyecto de elaboración y publicación de arreglos para banda a partir de parámetros específicos de dificultad técnica para los diversos instrumentos y la utilización de plantillas instrumentales estándar (reducida y básica). Incluye arreglos, score y partes, de seis piezas de', N'2002', 2002, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Arreglos', NULL, N'22.5x 31.5 cm', N'84 p. partitura general y 99p. partes', NULL, N'/editorial/thumbs/PNMC-ED-012.jpg', N'15', N'Alta', 0, 1, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-013', N'Acento', N'Arreglos para banda escuela', N'Volumen III', N'Acento', N'Hace parte de un proyecto de elaboración y publicación de arreglos para banda a partir de parámetros específicos de dificultad técnica para los diversos instrumentos y la utilización de plantillas instrumentales estándar (reducida y básica). Incluye arreglos, score y partes, de seis piezas, 3 de autor y 3 de la tradición: La redova y el shiotis; Leonor (danza); Maquerule (tradicional del Chocó); Chirimía y El rioblanqueño (Danza y Bambuco); Tu encanto (pasaje) y La piña madura (paseaíto)', N'2004', 2004, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Arreglos', NULL, N'22.5x 31.5 cm', N'100 p. Partitura general y 100 p. Partes', NULL, N'/editorial/thumbs/PNMC-ED-013.jpg', N'16', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-014', N'Obras originales para Banda', NULL, N'Volumen I', N'Obras originales para Banda', N'Hace parte de un proyecto de elaboración y publicación de arreglos para banda a partir de parámetros específicos de dificultad técnica para los diversos instrumentos y la utilización de plantillas instrumentales estándar (reducida y básica). Incluye arreglos, score y partes, de seis piezas 5 de autor y una de la tradición: La redova y el shiotis; Leonor (danza); Maquerule (tradicional del Chocó); Chirimía y El rioblanqueño (Danza y Bambuco); Tu encanto (pasaje) y La piña madura (paseaíto)', N'2010', 2010, NULL, NULL, N'es', N'Libro', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Arreglos', NULL, N'22.5x 31.5 cm + DVD', N'100 p', NULL, N'/editorial/thumbs/PNMC-ED-014.jpg', N'16', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-015', N'Cinco piezas de música colombiana para banda infantil y juvenil - Victoriano Valencia - Beca de creación, bandas', NULL, NULL, NULL, N'La publicación Cinco piezas de música colombiana para banda infantil y juvenil corresponde a la Beca de Creación convocada por el Programa Nacional de Estímulos del Ministerio de Cultura, que en año 2003 fue otorgada al compositor Victoriano Valencia. Incluye los arreglos, score y partes (en el CD adjunto), de tres obras: Profe (porro); Banda Vals (vals); Sanjuanito (sanjuanero) y Alvan (soka)', N'2008', 2008, NULL, NULL, N'es', N'Libro impreso + CD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Repertorio y partituras', NULL, N'22.8 x 31.5 cm. + CD', N'76 pp', NULL, N'/editorial/thumbs/PNMC-ED-015.jpg', N'17', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-016', N'Suite 200- Victoriano Valencia', NULL, NULL, NULL, N'La publicación SUITE 200, creada por el compositor Victoriano Valencia, fue comisionada por el Ministerio de Cultura de Colombia en el marco de la conmemoración del Bicentenario de la Independencia Nacional 1810-2010. Este CD contiene el audio de la obra, que se compone en 4 movimientos: Interdependencia; Territorios norte; Territorios sur y Utopía', N'2010', 2010, NULL, NULL, N'es', N'CD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Repertorio y partituras', NULL, N'12,5 x 12,5 cm', NULL, NULL, N'/editorial/thumbs/PNMC-ED-016.jpg', N'17', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-017', N'8 Arreglos para Banda', NULL, NULL, NULL, N'Esta publicación es invitación a una escucha activa y crítica de la mano de quienes conocen como pocos la importancia de las músicas populares y su valor musical y, por ello han puesto su creatividad en este proyecto, que sale a la luz como parte de la conmemoración del Bicentenario de la Independencia. Incluye arreglos, score y partes, de ocho piezas de', N'2010', 2010, NULL, NULL, N'es', N'Libro impreso + CD-ROM', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Banda', N'Banda', N'Arreglos', NULL, N'25 x 36 cm. + CD-ROM', N'146 p', NULL, N'/editorial/thumbs/PNMC-ED-017.jpg', N'18', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-018', N'Colección de arreglos para orquesta', NULL, NULL, NULL, N'Esta publicación realizada entre 2003 y 2005, en coproducción con la Fundación Batuta, compila en una colección de arreglos para orquesta de compositores colombianos e internacionales. Está conformada por piezas variadas en distintos géneros, con el fin de difundir repertorio musical tradicional y popular en versiones para orquesta. Las obras son: A shot in the dark de Henry Mancini, arreglo de Gustavo Parra; Porro de la suite No.2 de Gentil Montaña, arreglo de Johan Olaya; El currucucuy de Pedro Eustaquio Celis, arreglo de Gustavo Parra; Elvira de Pedro Eustaquio Celis, arreglo de Gustavo Parra; Gaita de Navidad de Aldemaro Romero, arreglo de Martha Sofía Rivera y Roberto Rubio; The Muppet’s Theme de Sam Pottle, arreglo de Gustavo Parra; Salsipuedes de Lucho Bermudez, arreglo de Juan Felipe Ávila; Gloria Eugenia de Manuel J. Bernal, arreglo de Jean Carlo Espindola; El toro barroso de DRA, arreglo de Johan Olaya y Tolú de Lucho Bermúdez, arreglo por Johan Olaya', N'2003', 2003, NULL, N'2003, 2004, 2005', N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Orquesta', N'Orquesta', N'Arreglos', NULL, N'21,5 x 28 cm', NULL, NULL, N'/editorial/thumbs/PNMC-ED-018.jpg', N'20', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-019', N'“Ramón el camaleón” Beca nacional de creación musical 2003', NULL, NULL, NULL, N'La publicación Ramón el camaleón corresponde a la Beca de Creación Musical 2003 convocada por el Programa Nacional de Estímulos del Ministerio de Cultura, que en año 2003 fue otorgada al compositor Luis Fernando Franco Duque. La estructura de esta composición es de 4 obras interrelacionadas, las cuales permiten incluir bandas e instrumentistas de distintos niveles; las obras son: Ramón el camaleón verde; Ramón el camaleón amarrillo; Ramón el camaleón rojo y Ramón el camaleón', N'2009', 2009, NULL, NULL, N'es', N'Estuche incluye 4 impresos, partitura general cada una identificada en la portada con un color: blanco, verde, amarillo y rojo + CD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Orquesta', N'Orquesta', N'Repertorio y partituras', N'Músicas tradicionales y regionales', N'24 x 34,5 cm. + CD y DVD', N'78 p. (Score)', NULL, N'/editorial/thumbs/PNMC-ED-019.jpg', N'21', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-020', N'8 arreglos para Orquesta', NULL, NULL, NULL, N'Esta publicación, que sale a la luz en el marco de la conmemoración del Bicentenario de la Independencia, hace un homenaje activo a obras de compositores colombianos de gran importancia, las cuales han sido arregladas por diversos por compositores que en la actualidad han realizado un gran trabajo contribuyendo al acervo musical colombiano. Las 8 obras son: Soy Colombiano de Rafael Godoy Lozano, arreglado por Luis Fernando León Rengifo; Colombia tierra querida de Luis Eduardo Bermúdez Acosta, arreglado por Rubén Darío Gómez Prada; Pueblito viejo de José Alejandro Morales, arreglado por Alfredo Mejía Vallejo; La ruana de Luis Carlos González y José Macías, arreglado por Jorge Andrés Arbeláez Rendón; Ay mi llanura de Arnulfo Briceño Contreras, arreglado por Eduardo Carrizosa Navarro; Mi buenaventura de Petronio Álvarez, arreglado por Jesús Orielso Santiago Jácome; El chambú de Luis E. Nieto, arreglado por José Revelo Burbano y La gota fría de Emiliano Zuleta Baquero, arreglado por Victoriano Valencia Rincón', N'2010', 2010, NULL, NULL, N'es', N'Libro y CD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Orquesta', N'Orquesta', N'Arreglos', NULL, N'24,5 x 36 cm. + CD', N'148 p', NULL, N'/editorial/thumbs/PNMC-ED-020.jpg', N'21', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-021', N'26 Arreglos Musicales - homenaje al maestro Lucho Bermúdez 100 años', NULL, NULL, NULL, N'Constituye un verdadero homenaje celebrar sus contribuciones creativas al panorama musical y poner al alcance de diferentes expresiones y prácticas musicales un repertorio que está en el imaginario colectivo mediante la realización de diversas versiones de una selección representativa de sus obras. Lucho Bermúdez nos regaló su genialidad creadora y nos puso a cantar y a bailar con la alegría de las cumbias, pasillos, porros, gaitas, mapales y seresesés, entre muchos otros géneros de su variado y rico repertorio. En esta producción se incluyen diferentes versiones de las piezas “Danza negra, Espíritu Colombiano, Fiesta de negritos, Tina y Carmen de Bolívar”, para banda, banda de marcha, coros, estudiantina, cuarteto de cuerdas, vientos, ensamble de percusión, orquesta sinfónica y orquestas de baile en diferentes conformaciones', N'2012', 2012, NULL, NULL, N'es', N'DVD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Música Popular y Tradicional > Homenajes', N'Banda', N'Arreglos', N'Coro y música vocal · Cuerdas típicas andinas · Orquesta · Músicas urbanas y populares', N'12,5 x 12,5 cm', NULL, NULL, N'/editorial/thumbs/PNMC-ED-021.jpg', N'23', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-022', N'Homenaje al maestro José A. Morales 100 años', NULL, NULL, NULL, N'Con esta producción celebramos las contribuciones creativas del tiplista, guitarrista, cantante y compositor José Alejandro Morales López, con diferentes versiones musicales de piezas muy emblemáticas que hacen parte de la memoria colectiva. Se trata de una selección representativa con obras como el bambuco Amistad, el vals Pueblito viejo, el pasillo Titiribí, el bambuco El Corazón de la caña y el bambuco Campesina Santandereana, en versiones para orquesta, banda, coro, cuarteto de cuerdas y cuerdas típicas', N'2013', 2013, NULL, NULL, N'es', N'DVD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Música Popular y Tradicional > Homenajes', N'Banda', N'Arreglos', N'Coro y música vocal · Cuerdas típicas andinas · Orquesta', N'12,5 x 12,5 cm', NULL, NULL, N'/editorial/thumbs/PNMC-ED-022.jpg', N'24', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-023', N'26 Arreglos Musicales - homenaje al maestro José Benito Barros Palomino 100 años', NULL, NULL, NULL, N'De los proyectos editoriales producidos para conmemorar los 100 años del maestro José Benito Barros Palomino, éste constituye uno de los más interesantes y diversos por su nivel de elaboración y aplicación. Se trata de 26 arreglos de 5 piezas emblemáticas del compositor: El pescador, Navidad negra, Pesares, Las pilanderas y el gallo tuerto; en versiones realizadas para coro de voces blancas, coro a voces mixtas, banda sinfónica de nivel 1 a 5, orquesta sinfónica, estudiantina, percusión de cámara, banda show, banda pelayera, cuarteto de cuerdas, quinteto de metales, grupo urbano, cuarteto de saxofones y orquesta tropical. por un excelso grupo de 26 compositores, intérpretes y arreglistas', N'2015', 2015, NULL, NULL, N'es', N'DVD', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Música Popular y Tradicional > Homenajes', N'Banda', N'Arreglos', N'Coro y música vocal · Cuerdas típicas andinas · Orquesta · Músicas urbanas y populares', N'12,5 x 12,5 cm', NULL, NULL, N'/editorial/thumbs/PNMC-ED-023.jpg', N'25', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-024', N'El Juglar y el pescador. Homenaje al Maestro José Benito Barros Palomino (1915 - 2007)', NULL, NULL, NULL, N'Al cumplirse el primer centenario del nacimiento del maestro José Benito Barros Palomino, el Ministerio de Cultura mediante la Resolución 345 honra su memoria, al declarar 2015 como el “Año José Barros”, rindiendo un homenaje a su vida y su fecunda creación. Los relatos alrededor de las canciones El Gallo Tuerto, Las Pilanderas, El Pescador (El alegre pescador), Pesares y Navidad Negra -que fueron elegidas por el público a través de la convocatoria realizada en la página web del Ministerio-, permitirán que niños y jóvenes colombianos y de otros países, conozcan, apropien e interpreten parte de la obra musical y del legado creativo del maestro José Benito Barros Palomino. El Ministerio de Cultura entrega al país esta publicación realizada desde el Plan Nacional de Música para la Convivencia –PNMC–, puesto en marcha en todo el territorio colombiano, desde hace doce años, para fortalecer la riqueza musical del país y promover su conocimiento, divulgación, apropiación y valoración', N'2015', 2015, NULL, NULL, N'es', N'libro y Multimedia', N'Físico', N'Nacional', NULL, N'Repertorio', N'Repertorio > Música Popular y Tradicional > Homenajes', N'Músicas tradicionales y regionales', N'Repertorio y partituras', NULL, N'27.5 x 25 cm. Pasta dura, 27 x 20 cosido al gancho', N'35 p', NULL, N'/editorial/thumbs/PNMC-ED-024.jpg', N'26', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-025', N'Cartilla de Pre-Banda', NULL, NULL, NULL, N'Esta cartilla fue realizada como una recopilación de sugerencias, canciones y juegos para trabajar procesos de iniciación musical en el espacio pedagógico de la pre-banda. Está dividida en cuatro capítulos: coordinación y atención, aspecto vivencia, aspecto conceptual y ejercicios complementarios. Esta cartilla está acompañada de un video realizado en la época en formato analógico VHS que contiene información básica complementaria', N'2000', 2000, NULL, N'1ª ed. 2000 y 2ª ed. 2002', N'es', N'Libro impreso + Video grabación VHS', N'Físico', N'Nacional', NULL, N'Formación', N'Formación > Pedagogía Instrumental > Guías y Cuadernos de instrumento', N'Banda', N'Pedagogía y formación', NULL, N'22x 28 cm', N'68 p. + Video VHS', N'24’45’’', N'/editorial/thumbs/PNMC-ED-025.jpg', N'28', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-026', N'Cuando las bandas suenan instrumentos llevan, Video de iniciación instrumental', NULL, NULL, NULL, N'“El sonido es un fenómeno natural. La música en cambio es el resultado consciente del sonido por parte del hombre, hasta convertirlo en un arte y una ciencia”. Es la cita con la que inicia el video de iniciación musical Cuando las bandas suenan instrumentos llevan. En él se registran experiencias musicales y testimonios de jóvenes directores e intérpretes. Incluye también un acercamiento a cada uno de los instrumentos de la banda de una forma muy didáctica realizada por maestros instrumentistas con participación de los estudiantes, en el que se describe cada instrumento con detalle técnico, la descripción de las partes, ensamblaje, accesorios, postura corporal, posición de los dedos, ubicación de la embocadura, emisión y calidad del sonido, respiración, afinación, con ilustraciones interpretativas individuales y de conjunto, y finalmente la banda en plena sonoridad', N'1999', 1999, NULL, NULL, N'es', N'Video grabación VHS', NULL, N'Nacional', NULL, N'Formación', N'Formación > Pedagogía Instrumental > Guías y Cuadernos de instrumento', N'Banda', N'Pedagogía y formación', NULL, N'19 x 10.5 cm', NULL, N'47’50’’', N'/editorial/thumbs/PNMC-ED-026.jpg', N'29', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-027', N'Cartilla de Arreglos para Banda. Nivel 1', NULL, NULL, NULL, N'La Cartilla de Arreglos para Banda. Nivel 1 es una guía para arreglistas, directores de banda y músicos en general, interesados en proyectarse dentro del campo de los arreglos, adaptaciones y otras formas de producción de repertorios para las bandas de viento del país. La cartilla pretende actuar tanto en una perspectiva organizadora como en la generación de nuevas rutas y materiales que alimenten la práctica cotidiana. Contiene una información nutrida de herramientas para el análisis musical, incluyendo comportamientos de músicas regionales colombianas, que apoyarán la labor del director en el estudio de partituras y montaje y la de los integrantes, potenciando su desempeño interpretativo', N'2005', 2005, NULL, NULL, N'es', N'Libro impreso', N'Físico', N'Nacional', NULL, N'Formación', N'Formación > Pedagogía Instrumental > Guías y Cuadernos de instrumento', N'Banda', N'Arreglos', NULL, N'22x 28 cm', N'124 p', NULL, N'/editorial/thumbs/PNMC-ED-027.jpg', N'30', N'Alta', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-028', N'Guía de iniciación al clarinete', NULL, NULL, NULL, N'La Guía de Iniciación al clarinete es un documento destinado a dar apoyo didáctico a los directores e instrumentistas en su proceso formativo. Contiene las bases para el inicio de un proceso de formación instrumental, presentando el clarinete, su historia, descripción, cuidados, postura corporal al tocar, producción de sonido, embocadura, articulación, dinámicas, afinación, cañas y algunos problemas técnicos', N'2003', 2003, NULL, NULL, N'es', N'Libro, Guía', N'Físico', N'Nacional', NULL, N'Formación', N'Formación > Pedagogía Instrumental > Guías y Cuadernos de instrumento', N'Banda', N'Pedagogía y formación', N'Orquesta', N'21.5 x 28 cm', N'35 p', NULL, N'/editorial/thumbs/PNMC-ED-028.jpg', N'31', N'Alta', 0, 0, N'ISBN reconstruido del prefijo 958- (original PPT: 8052-83-1)', N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-029', N'Cuaderno de ejercicios para clarinete', NULL, NULL, NULL, N'Contiene las bases iniciales del proceso de formación en el clarinete, con una serie de contenidos instrumentales y conceptos musicales básicos – como el estudio de los sonidos y sus respectivas digitaciones, algunos recursos técnicos del instrumento, ejercicios y repertorio- ordenados de manera gradual en diez unidades y tabla de digitaciones, acorde con las necesidades formativas de nuestro medio musical. Al igual que la Guía de iniciación al clarinete, este Cuaderno es un mapa de introducción a la formación instrumental, con el cual esperamos que el estudiante construya una habilidad instrumental y un criterio musical más eficaces y satisfactorios a largo plazo', N'2002', 2002, NULL, NULL, N'es', N'Libro', N'Físico', N'Nacional', NULL, N'Formación', N'Formación > Pedagogía Instrumental > Guías y Cuadernos de instrumento', N'Banda', N'Pedagogía y formación', NULL, N'21.5 x 27.5 cm', N'63p', NULL, N'/editorial/thumbs/PNMC-ED-029.jpg', N'31', N'Alta', 0, 0, N'ISBN reconstruido del prefijo 958- (original PPT: 8159-03-2)', N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-030', N'Guía de iniciación a la flauta traversa', NULL, NULL, NULL, N'La Guía de Iniciación a la flauta traversa es un documento destinado a dar apoyo didáctico a los directores e instrumentistas en su proceso formativo. Contiene las bases para el inicio de un proceso de formación instrumental, presentando la flauta traversa, su historia, descripción, cuidados, postura corporal al tocar, producción de sonido, embocadura, articulación, dinámicas, afinación y algunos problemas técnicos', N'2003', 2003, NULL, NULL, N'es', N'Libro, Guía', N'Físico', N'Nacional', NULL, N'Formación', N'Formación > Pedagogía Instrumental > Guías y Cuadernos de instrumento', N'Banda', N'Pedagogía y formación', N'Orquesta', N'21.5 x 28 cm', N'36 p', NULL, N'/editorial/thumbs/PNMC-ED-030.jpg', N'32', N'Alta', 0, 0, N'ISBN reconstruido del prefijo 958- (original PPT: 8052-84-X)', N'pendiente_revision', N'borrador', N'pendiente'),
