    (N'PNMC-ED-169', N'Escuela Municipal de Música de Mosquera', NULL, NULL, NULL, NULL, N'2015', 2015, NULL, NULL, N'es', N'Videoclip', N'Digital', N'Andina', N'Cundinamarca - Mosquera', N'Creación y Circulación', N'Creación y Circulación > Piezas divulgativas > Premios Nacionales de Música', N'Transversal / General', N'Pedagogía y formación', NULL, NULL, NULL, NULL, N'/editorial/thumbs/PNMC-ED-169.jpg', N'147', N'Media', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-170', N'Música para la convivencia 11 años', NULL, NULL, NULL, NULL, N'2014', 2014, NULL, NULL, N'es', N'Video', NULL, N'Nacional', NULL, N'Creación y Circulación', N'Creación y Circulación > Piezas divulgativas > Premios Nacionales de Música', N'Transversal / General', N'Estímulos y convocatorias', NULL, NULL, NULL, NULL, N'/editorial/thumbs/PNMC-ED-170.jpg', N'148', N'Media', 1, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente'),
    (N'PNMC-ED-171', N'Coro virtual de Colombia 2015', NULL, NULL, NULL, N'Proyecto que pone la tecnología al servicio de la práctica coral, primera iniciativa de convocatoria abierta para la realización de un coro virtual nacional en el país . Se realizó en el marco del año homenaje al maestro en el centenario de su nacimiento José Benito Barros Palomino', N'2015', 2015, NULL, NULL, N'es', N'Producción colaborativa virtual', N'Digital', N'Nacional', NULL, N'Creación y Circulación', N'Creación y Circulación > Piezas divulgativas > Premios Nacionales de Música', N'Coro y música vocal', N'Estímulos y convocatorias', NULL, NULL, NULL, NULL, N'/editorial/thumbs/PNMC-ED-171.jpg', N'149', N'Media', 0, 0, NULL, N'pendiente_revision', N'borrador', N'pendiente')
) AS v (Codigo, Titulo, Subtitulo, DesignacionVolumen, SerieOColeccion, Resumen, FechaEdtf,
        AnioInicio, AnioFin, NotaFecha, Idioma, TipoPublicacion, Formato, Ambito, AmbitoTexto,
        SeccionPrincipal, RutaSeccion, PracticaMusical, Subcategoria, CategoriaSecundaria,
        TamanoFormato, Paginas, Duracion, MiniaturaRuta, DiapositivaOrigen, Confianza,
        RevisarClasificacion, RevisarCreditos, NotasCatalogacion,
        EstadoCatalogacion, EstadoPublicacion, DerechosEstado)
WHERE NOT EXISTS (SELECT 1 FROM dbo.PublicacionesEditoriales p WHERE p.Codigo = v.Codigo);
