WHERE NOT EXISTS (SELECT 1 FROM dbo.AccesosEditoriales x WHERE x.PublicacionEditorialId = p.IdPublicacionEditorial AND x.Tipo = v.Tipo AND ISNULL(x.Url, N'') = ISNULL(v.Url, N'') AND ISNULL(x.UbicacionFisica, N'') = ISNULL(v.UbicacionFisica, N''))
;
GO

